def normalize(M):return M/M.sum()
def role(M):return (M.sum(0)+M.sum(1))/(2*M.sum())
def tv(A,B):return float(abs(normalize(A)-normalize(B)).sum()/2)
def conditional_js(A,B):
 use=(A.sum(1)>0)&(B.sum(1)>0);weights=B.sum(1)[use];weights=weights/weights.sum();return float(sum(w*jensenshannon(normalize(A[i]),normalize(B[i]),base=2)**2 for i,w in zip(np.flatnonzero(use),weights)))
def predict(D,mp,ma,star=None,receiver_adjust=False):
 """Row target = old nonstar outgoing passes per recorded minute times new minutes.
 Primary model preserves recipient probabilities among available teammates.
 Secondary model also multiplies recipient probabilities by receiver minute ratio.
 New sender / emptied support uses recipient-minute weights and a pooled sender rate.
 """
 n=len(D);active=ma>0
 if star is not None:active[star]=False
 mp=np.asarray(mp,float);ma=np.asarray(ma,float);pooled=float(D.sum()/mp.sum());rates=np.divide(D.sum(1),mp,out=np.full(n,pooled),where=mp>0);target=rates*ma;target[~active]=0;M=np.zeros_like(D,float);fallback=np.zeros(n,bool);new=np.zeros(n,bool);lost_support=np.zeros(n,bool)
 for i in range(n):
  if not active[i]:continue
  mask=active.copy();mask[i]=False;kernel=D[i].copy();kernel[~mask]=0
  if receiver_adjust:
   ratio=np.divide(ma,mp,out=np.zeros(n),where=mp>0);kernel*=ratio
  if kernel.sum()==0:
   # A previously observed zero-pass sender stays at zero; unsupported new senders
   # or rows whose old recipients are unavailable require an explicit fallback.
   if target[i]==0:continue
   kernel=ma*mask;fallback[i]=True;new[i]=mp[i]==0;lost_support[i]=mp[i]>0
  if kernel.sum()>0:M[i]=target[i]*kernel/kernel.sum()
  else:target[i]=0
 return M,dict(rate=rates,target=target,fallback=fallback,new_sender=((mp==0)&(D.sum(1)==0)&active),rate_fallback=((mp==0)&active),lost_support=lost_support,pooled_rate=pooled)

