   if pdf is not None:
    union=P+A;G=nx.from_numpy_array((union+union.T)>0);G=G.subgraph(np.flatnonzero(union.sum(0)+union.sum(1)>0)).copy();opts=dict(seed=42,weight=None,iterations=400,k=1.5/np.sqrt(len(G)))
    if 'method' in inspect.signature(nx.spring_layout).parameters:opts['method']='force'
    pos=nx.spring_layout(G,**opts);coords=np.array(list(pos.values()));lo=coords.min(0)-.25;hi_lim=coords.max(0)+.25;scale=max((1000*normalize(B)).max() for B in matrices.values());fig,axes=plt.subplots(2,2,figsize=(20,15))
