    fig.suptitle(f'{z.team} | {z.star_name} absent | {z.present_games} played / {z.absent_games} missed\nRecorded-minutes diagnostic: not a pre-absence forecast',fontsize=18);fig.text(.5,.02,'Node areas use each panel’s own passing-involvement shares; common scales and fixed Fruchterman–Reingold positions. True isolates omitted.\nSender model preserves baseline recipient probabilities among available teammates. Secondary model also adjusts recipient exposure by minute ratios.\nActual absence-game minutes are known inputs. New senders use an explicit pooled-rate / minute-weighted fallback; exported and quantified.',ha='center',fontsize=10);fig.tight_layout(rect=[0,.07,1,.94]);fig.savefig(folder/(z.team+'_minutes_models.png'),dpi=130);pdf.savefig(fig);plt.close(fig)
